"""Migration of Meridian CRM 4.2 account validation rules."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a field value, preserving legacy missing-field-as-empty semantics."""
    if row is None:
        return ""
    return row.get(column, "")


def _text(value: Any) -> str:
    """Convert values for legacy string functions; missing/null values are empty."""
    if value is None:
        return ""
    return str(value)


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric-context coercion for empty or missing values."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Validate an ACCT_MASTER post-write image in legacy rule-file order."""
    del today  # Included for the fixed interface; these rules do not use TODAY().

    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if len(_text(_value(record, "ACCT_NM"))) < 2:
            fail("E1001", "Account name too short")

        # ACC-002
        if _value(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            fail("E1002", "Invalid account type")

        # ACC-003
        ann_rev = _value(record, "ANN_REV")
        if ann_rev is None or ann_rev == "":
            ann_rev = 0
        if _numeric(ann_rev) < 0:
            fail("E1003", "Annual revenue negative")

    if event == "UPDATE":
        # ACC-004
        if (
            _value(old, "CRED_HOLD") == "Y"
            and _value(record, "CRED_HOLD") == "N"
            and _numeric(_value(record, "CRED_LIMIT")) <= 0
        ):
            fail("E1004", "Cannot release credit hold with zero credit limit")

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if len(_text(_value(record, "REGION_CD"))) != 3:
            fail("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
